src/auth/mailer.js.source:
const nodemailer = require("nodemailer");
const { getProductName, getProductUrl } = require("../config/product");
const { buildRecoveryBody, buildWelcomeBody } = require("./email-templates");

/**
 * Error thrown when a product email cannot be delivered.
 */
class MailDeliveryError extends Error {
  /**
   * @param {string} message - Error description.
   * @param {Error} [cause] - Original nodemailer error.
   */
  constructor(message, cause) {
    super(message, cause ? { cause } : undefined);
    this.name = "MailDeliveryError";
  }
}

let transport = null;

/**
 * Builds the Gmail transport lazily using GMAIL_USERNAME and GMAIL_TOKEN.
 * @returns {import("nodemailer").Transporter} The configured transport.
 */
function getTransport() {
  if (!transport) {
    transport = nodemailer.createTransport({
      service: "gmail",
      auth: {
        user: process.env.GMAIL_USERNAME,
        pass: process.env.GMAIL_TOKEN,
      },
    });
  }

  return transport;
}

/**
 * Replaces the transport; used by tests to avoid real SMTP traffic.
 * @param {object} next - Transport replacement.
 * @returns {void}
 */
function setTransport(next) {
  transport = next;
}

/**
 * Discards the current transport so the next send builds a new one.
 * @returns {void}
 */
function resetTransport() {
  transport = null;
}

/**
 * Delivers a message through the current transport, wrapping any transport
 * error in a {@link MailDeliveryError}.
 * @param {{ to: string, subject: string, text: string }} message - Message to deliver.
 * @param {string} failureMessage - Error message to expose when delivery fails.
 * @returns {Promise<void>}
 * @throws {MailDeliveryError} When the transport cannot deliver the message.
 */
async function deliver(message, failureMessage) {
  try {
    await getTransport().sendMail({
      from: process.env.GMAIL_USERNAME,
      ...message,
    });
  } catch (error) {
    throw new MailDeliveryError(failureMessage, error);
  }
}

/**
 * Sends the recovery code to the given email through Gmail.
 * @param {string} email - Recipient address.
 * @param {string} code - Plain 8-digit recovery code.
 * @returns {Promise<void>}
 * @throws {MailDeliveryError} When the transport cannot deliver the message.
 */
async function sendRecoveryCode(email, code) {
  const productName = getProductName();

  return deliver(
    {
      to: email,
      subject: `Recuperación de contraseña - ${productName}`,
      text: buildRecoveryBody(code, productName),
    },
    "Could not send the recovery email",
  );
}

/**
 * Sends the welcome email to a newly created user through Gmail.
 * @param {string} email - Recipient address.
 * @param {string|null|undefined} name - User name, used in the greeting.
 * @returns {Promise<void>}
 * @throws {MailDeliveryError} When the transport cannot deliver the message.
 */
async function sendWelcomeEmail(email, name) {
  const productName = getProductName();
  const productUrl = getProductUrl();

  return deliver(
    {
      to: email,
      subject: `¡Bienvenido a ${productName}!`,
      text: buildWelcomeBody(name, productName, productUrl),
    },
    "Could not send the welcome email",
  );
}

module.exports = {
  MailDeliveryError,
  getTransport,
  setTransport,
  resetTransport,
  sendRecoveryCode,
  sendWelcomeEmail,
};

src/auth/welcome.js.source:
const { sendWelcomeEmail } = require("./mailer");
const logger = require("../config/logger");

const WELCOME_FAILURE_MESSAGE = "Could not send the welcome email";

/**
 * Notifies a freshly created user by email without letting a delivery failure
 * break the surrounding request.
 *
 * The notification is a best-effort side effect: the caller has already
 * persisted the user, so a broken SMTP connection must never turn a 201 into a
 * 500. Failures are logged and swallowed. The delivery and logging strategies
 * can be overridden, which keeps the policy decoupled from the concrete mailer.
 *
 * @param {{ email: string, name?: string|null }} user - Created user.
 * @param {{ send?: Function, log?: { error: Function } }} [dependencies]
 *   Delivery and logging strategies; defaults to the mailer and app logger.
 * @returns {Promise<void>} Resolves once the attempt (success or failure) ends.
 */
async function notifyWelcomeUser(user, dependencies = {}) {
  const { send = sendWelcomeEmail, log = logger } = dependencies;

  try {
    await send(user.email, user.name);
  } catch (error) {
    log.error(WELCOME_FAILURE_MESSAGE, { email: user.email, error });
  }
}

module.exports = { notifyWelcomeUser };

src/config/product.js.source:
const DEFAULT_APP_NAME = "Super King";
const DEFAULT_APP_URL = "https://dashboard.asic-guanipa.online/";

/**
 * Reads `APP_NAME` and resolves the product name shown in the emails.
 *
 * An unset or empty variable falls back to {@link DEFAULT_APP_NAME}. The value
 * is read on every call so a configuration change is reflected without
 * reloading the module.
 *
 * @returns {string} Resolved product name.
 */
function getProductName() {
  return process.env.APP_NAME || DEFAULT_APP_NAME;
}

/**
 * Reads `APP_URL` and resolves the web link included in the emails.
 *
 * An unset or empty variable falls back to {@link DEFAULT_APP_URL}. The
 * configured value is returned exactly as-is, keeping its trailing slash when
 * present.
 *
 * @returns {string} Resolved web link.
 */
function getProductUrl() {
  return process.env.APP_URL || DEFAULT_APP_URL;
}

module.exports = {
  DEFAULT_APP_NAME,
  DEFAULT_APP_URL,
  getProductName,
  getProductUrl,
};

