process.env.JWT_SECRET = "test-secret";

jest.mock("../models/user", () => ({
  findOne: jest.fn(),
  count: jest.fn(),
  create: jest.fn(),
}));

jest.mock("../models/role", () => ({ findOne: jest.fn() }));

jest.mock("../models/password-reset-code", () => ({
  findOne: jest.fn(),
  create: jest.fn(),
  update: jest.fn(),
}));

jest.mock("../database", () => ({ transaction: jest.fn() }));

jest.mock("./mailer", () => {
  const actual = jest.requireActual("./mailer");

  return {
    ...actual,
    sendRecoveryCode: jest.fn(),
    sendWelcomeEmail: jest.fn(),
  };
});

jest.mock("../config/logger", () => ({
  error: jest.fn(),
  info: jest.fn(),
  warn: jest.fn(),
}));

const express = require("express");
const request = require("supertest");
const User = require("../models/user");
const Role = require("../models/role");
const sequelize = require("../database");
const authRouter = require("./index");
const { sendWelcomeEmail } = require("./mailer");
const logger = require("../config/logger");

const app = express();
app.use(express.json());
app.use("/auth", authRouter);

const ADMIN_ROLE = { id: 1, name: "admin" };
const TRANSACTION = { LOCK: { UPDATE: "UPDATE" } };
const validBody = {
  username: "admin",
  email: "admin@superking.com",
  password: "secret123",
  name: "Administrador",
};

const register = (body) => request(app).post("/auth/register-admin").send(body);

beforeEach(() => {
  User.findOne.mockReset();
  User.count.mockReset();
  User.create.mockReset();
  Role.findOne.mockReset();
  sequelize.transaction.mockImplementation((callback) => callback(TRANSACTION));
  sendWelcomeEmail.mockReset();
  logger.error.mockReset();
});

describe("GET /auth/setup-status", () => {
  it("responds hasAdmin false when the administrator role is missing", async () => {
    Role.findOne.mockResolvedValue(null);

    const response = await request(app).get("/auth/setup-status");

    expect(response.status).toBe(200);
    expect(response.body).toEqual({ hasAdmin: false });
    expect(User.count).not.toHaveBeenCalled();
  });

  it("responds hasAdmin false when there are no administrators", async () => {
    Role.findOne.mockResolvedValue(ADMIN_ROLE);
    User.count.mockResolvedValue(0);

    const response = await request(app).get("/auth/setup-status");

    expect(response.status).toBe(200);
    expect(response.body).toEqual({ hasAdmin: false });
    expect(Role.findOne).toHaveBeenCalledWith({
      where: { name: "admin" },
    });
    expect(User.count).toHaveBeenCalledWith({ where: { roleId: 1 } });
  });

  it("responds hasAdmin true when at least one administrator exists", async () => {
    Role.findOne.mockResolvedValue(ADMIN_ROLE);
    User.count.mockResolvedValue(2);

    const response = await request(app).get("/auth/setup-status");

    expect(response.status).toBe(200);
    expect(response.body).toEqual({ hasAdmin: true });
  });
});

describe("POST /auth/register-admin", () => {
  it("creates the first administrator inside a transaction", async () => {
    Role.findOne.mockResolvedValue(ADMIN_ROLE);
    User.findOne.mockResolvedValue(null);
    User.create.mockResolvedValue({
      id: 1,
      username: "admin",
      email: "admin@superking.com",
      name: "Administrador",
      roleId: 1,
    });

    const response = await register(validBody);

    expect(response.status).toBe(201);
    expect(response.body).toEqual({
      id: 1,
      username: "admin",
      email: "admin@superking.com",
      name: "Administrador",
      role: "admin",
      isBlocked: false,
    });
    expect(response.body).not.toHaveProperty("password");
    expect(response.body).not.toHaveProperty("roleId");
    expect(sequelize.transaction).toHaveBeenCalledTimes(1);
    expect(Role.findOne).toHaveBeenCalledWith({
      where: { name: "admin" },
      transaction: TRANSACTION,
      lock: "UPDATE",
    });
    expect(User.findOne).toHaveBeenCalledWith({
      where: { roleId: 1 },
      transaction: TRANSACTION,
    });
    expect(User.create).toHaveBeenCalledWith(
      {
        username: "admin",
        email: "admin@superking.com",
        password: "secret123",
        name: "Administrador",
        roleId: 1,
      },
      { transaction: TRANSACTION },
    );
  });

  it("forces the administrator role even when the client sends another role", async () => {
    Role.findOne.mockResolvedValue(ADMIN_ROLE);
    User.findOne.mockResolvedValue(null);
    User.create.mockResolvedValue({
      id: 1,
      username: "admin",
      email: "admin@superking.com",
      name: null,
      roleId: 1,
    });

    const response = await register({ ...validBody, role: "customer" });

    expect(response.status).toBe(201);
    expect(response.body.role).toBe("admin");
    expect(User.create).toHaveBeenCalledWith(
      {
        username: "admin",
        email: "admin@superking.com",
        password: "secret123",
        name: "Administrador",
        roleId: 1,
      },
      { transaction: TRANSACTION },
    );
  });

  it("sends a welcome email after the administrator is created", async () => {
    Role.findOne.mockResolvedValue(ADMIN_ROLE);
    User.findOne.mockResolvedValue(null);
    User.create.mockResolvedValue({
      id: 1,
      username: "admin",
      email: "admin@superking.com",
      name: "Administrador",
      roleId: 1,
    });
    sendWelcomeEmail.mockResolvedValue(undefined);

    const response = await register(validBody);

    expect(response.status).toBe(201);
    expect(sendWelcomeEmail).toHaveBeenCalledTimes(1);
    expect(sendWelcomeEmail).toHaveBeenCalledWith(
      "admin@superking.com",
      "Administrador",
    );
  });

  it("still responds 201 and logs when the welcome email fails", async () => {
    Role.findOne.mockResolvedValue(ADMIN_ROLE);
    User.findOne.mockResolvedValue(null);
    User.create.mockResolvedValue({
      id: 1,
      username: "admin",
      email: "admin@superking.com",
      name: "Administrador",
      roleId: 1,
    });
    const error = new Error("connection refused");
    sendWelcomeEmail.mockRejectedValue(error);

    const response = await register(validBody);

    expect(response.status).toBe(201);
    expect(response.body).toEqual({
      id: 1,
      username: "admin",
      email: "admin@superking.com",
      name: "Administrador",
      role: "admin",
      isBlocked: false,
    });
    expect(logger.error).toHaveBeenCalledWith(
      "Could not send the welcome email",
      { email: "admin@superking.com", error },
    );
  });

  it("responds 409 when an administrator already exists", async () => {
    Role.findOne.mockResolvedValue(ADMIN_ROLE);
    User.findOne.mockResolvedValue({ id: 9 });

    const response = await register(validBody);

    expect(response.status).toBe(409);
    expect(response.body).toEqual({ message: "Admin already exists" });
    expect(User.create).not.toHaveBeenCalled();
    expect(sendWelcomeEmail).not.toHaveBeenCalled();
  });

  it("responds 500 when the administrator role is not configured", async () => {
    Role.findOne.mockResolvedValue(null);

    const response = await register(validBody);

    expect(response.status).toBe(500);
    expect(response.body).toEqual({ message: "Server error" });
    expect(User.create).not.toHaveBeenCalled();
    expect(sendWelcomeEmail).not.toHaveBeenCalled();
  });

  it.each([
    ["all fields are missing", {}, "username, email and password are required"],
    [
      "username is missing",
      { email: "a@b.com", password: "secret123" },
      "username is required",
    ],
    [
      "email is missing",
      { username: "admin", password: "secret123" },
      "email is required",
    ],
    [
      "password is missing",
      { username: "admin", email: "a@b.com" },
      "password is required",
    ],
  ])("responds 400 when %s", async (_case, body, message) => {
    const response = await register(body);

    expect(response.status).toBe(400);
    expect(response.body).toEqual({ message });
    expect(sequelize.transaction).not.toHaveBeenCalled();
  });

  it("responds 422 with field errors for invalid fields", async () => {
    const response = await register({
      username: "admin",
      email: "invalid@",
      password: "short",
    });

    expect(response.status).toBe(422);
    expect(response.body).toEqual({
      errors: {
        email: "Invalid email",
        password: "Password must be at least 8 characters long",
      },
    });
    expect(sequelize.transaction).not.toHaveBeenCalled();
  });
});

src/auth/auth.test.js.source:
process.env.JWT_SECRET = "test-secret";

jest.mock("../models/user", () => ({
  findOne: jest.fn(),
  findByPk: jest.fn(),
}));

jest.mock("../models/role", () => ({ findOne: jest.fn() }));

jest.mock("../models/password-reset-code", () => ({
  findOne: jest.fn(),
  create: jest.fn(),
  update: jest.fn(),
}));

jest.mock("../database", () => ({ transaction: jest.fn() }));

const express = require("express");
const request = require("supertest");
const bcrypt = require("bcrypt");
const jwt = require("jsonwebtoken");
const { Op } = require("sequelize");
const User = require("../models/user");
const Role = require("../models/role");
const authRouter = require("./index");

const app = express();
app.use(express.json());
app.use("/auth", authRouter);

const SECRET = "test-secret";
const PASSWORD = "secret123";
const passwordHash = bcrypt.hashSync(PASSWORD, 10);
const user = {
  id: 1,
  username: "juan",
  email: "juan@example.com",
  name: "Juan",
  password: passwordHash,
  role: { name: "customer" },
  isBlocked: false,
};
const publicUser = {
  id: 1,
  username: "juan",
  email: "juan@example.com",
  name: "Juan",
  role: "customer",
  isBlocked: false,
};

const login = (body) => request(app).post("/auth/login").send(body);
const signToken = (payload, options) => jwt.sign(payload, SECRET, options);

beforeEach(() => {
  User.findOne.mockReset();
  User.findByPk.mockReset();
});

describe("POST /auth/login", () => {
  it("logs in with a valid email and returns a signed JWT", async () => {
    User.findOne.mockResolvedValue(user);

    const response = await login({
      identifier: "juan@example.com",
      password: PASSWORD,
    });

    expect(response.status).toBe(200);
    expect(response.body.user).toEqual(publicUser);
    expect(response.body.user).not.toHaveProperty("password");
    expect(User.findOne).toHaveBeenCalledWith({
      where: {
        [Op.or]: [
          { email: "juan@example.com" },
          { username: "juan@example.com" },
        ],
      },
      include: { model: Role, as: "role" },
    });

    const decoded = jwt.verify(response.body.token, SECRET, {
      algorithms: ["HS256"],
    });
    expect(decoded.sub).toBe(1);
    expect(decoded.username).toBe("juan");
    expect(decoded.email).toBe("juan@example.com");
    expect(decoded.role).toBe("customer");
    expect(decoded.iat).toEqual(expect.any(Number));
    expect(decoded.exp).toEqual(expect.any(Number));
    expect(decoded.exp - decoded.iat).toBe(3600);
  });

  it("logs in with a valid username", async () => {
    User.findOne.mockResolvedValue(user);

    const response = await login({ identifier: "juan", password: PASSWORD });

    expect(response.status).toBe(200);
    expect(User.findOne).toHaveBeenCalledWith({
      where: { [Op.or]: [{ email: "juan" }, { username: "juan" }] },
      include: { model: Role, as: "role" },
    });
    const decoded = jwt.verify(response.body.token, SECRET, {
      algorithms: ["HS256"],
    });
    expect(decoded.username).toBe("juan");
  });

  it("honors the JWT_EXPIRES_IN environment variable", async () => {
    User.findOne.mockResolvedValue(user);
    process.env.JWT_EXPIRES_IN = "2h";

    try {
      const response = await login({ identifier: "juan", password: PASSWORD });
      const decoded = jwt.verify(response.body.token, SECRET, {
        algorithms: ["HS256"],
      });
      expect(decoded.exp - decoded.iat).toBe(7200);
    } finally {
      delete process.env.JWT_EXPIRES_IN;
    }
  });

  it("responds 401 when the user does not exist", async () => {
    User.findOne.mockResolvedValue(null);

    const response = await login({ identifier: "nobody", password: PASSWORD });

    expect(response.status).toBe(401);
    expect(response.body).toEqual({ message: "Invalid credentials" });
  });

  it("responds 401 when the password is incorrect", async () => {
    User.findOne.mockResolvedValue(user);

    const response = await login({
      identifier: "juan",
      password: "wrong-password",
    });

    expect(response.status).toBe(401);
    expect(response.body).toEqual({ message: "Invalid credentials" });
  });

  it("responds 403 when the credentials are valid but the user is blocked", async () => {
    User.findOne.mockResolvedValue({ ...user, isBlocked: true });

    const response = await login({ identifier: "juan", password: PASSWORD });

    expect(response.status).toBe(403);
    expect(response.body).toEqual({ message: "User is blocked" });
    expect(response.body).not.toHaveProperty("token");
  });

  it("responds 400 when the request has no body", async () => {
    const response = await request(app).post("/auth/login");

    expect(response.status).toBe(400);
    expect(response.body).toEqual({
      message: "identifier and password are required",
    });
  });

  it.each([
    ["both fields are missing", {}],
    ["the identifier is missing", { password: PASSWORD }],
    ["the password is missing", { identifier: "juan" }],
    ["the identifier is empty", { identifier: "", password: PASSWORD }],
  ])("responds 400 when %s", async (_case, body) => {
    const response = await login(body);

    expect(response.status).toBe(400);
    expect(response.body).toEqual({
      message: "identifier and password are required",
    });
  });

  it("responds 422 with field errors when the email is invalid", async () => {
    const response = await login({ identifier: "invalid@", password: "short" });

    expect(response.status).toBe(422);
    expect(response.body).toEqual({
      errors: {
        email: "Invalid email",
        password: "Password must be at least 8 characters long",
      },
    });
    expect(User.findOne).not.toHaveBeenCalled();
  });

  it("responds 422 when the password is too short", async () => {
    const response = await login({ identifier: "juan", password: "short" });

    expect(response.status).toBe(422);
    expect(response.body).toEqual({
      errors: { password: "Password must be at least 8 characters long" },
    });
    expect(User.findOne).not.toHaveBeenCalled();
  });
});

describe("GET /auth/me", () => {
  const token = signToken(
    { sub: 1, username: "juan", email: "juan@example.com", role: "customer" },
    { expiresIn: "1h" },
  );

  it("returns the authenticated user with the role and without the password", async () => {
    User.findByPk.mockResolvedValue(user);

    const response = await request(app)
      .get("/auth/me")
      .set("Authorization", `Bearer ${token}`);

    expect(response.status).toBe(200);
    expect(response.body).toEqual(publicUser);
    expect(response.body).not.toHaveProperty("password");
    expect(response.body).not.toHaveProperty("roleId");
    expect(User.findByPk).toHaveBeenCalledWith(1, {
      include: { model: Role, as: "role" },
    });
  });

  it("responds 401 without an authorization header", async () => {
    const response = await request(app).get("/auth/me");

    expect(response.status).toBe(401);
    expect(response.body).toEqual({ message: "Unauthorized" });
  });

  it("responds 401 when the token is invalid", async () => {
    const response = await request(app)
      .get("/auth/me")
      .set("Authorization", "Bearer not-a-jwt");

    expect(response.status).toBe(401);
    expect(response.body).toEqual({ message: "Unauthorized" });
  });

  it("responds 401 when the token uses a different algorithm", async () => {
    User.findByPk.mockResolvedValue(user);
    const hs384 = signToken(
      { sub: 1 },
      { algorithm: "HS384", expiresIn: "1h" },
    );

    const response = await request(app)
      .get("/auth/me")
      .set("Authorization", `Bearer ${hs384}`);

    expect(response.status).toBe(401);
    expect(response.body).toEqual({ message: "Unauthorized" });
    expect(User.findByPk).not.toHaveBeenCalled();
  });

  it("responds 401 when the token is expired", async () => {
    const expired = signToken({ sub: 1 }, { expiresIn: "-1s" });

    const response = await request(app)
      .get("/auth/me")
      .set("Authorization", `Bearer ${expired}`);

    expect(response.status).toBe(401);
    expect(response.body).toEqual({ message: "Unauthorized" });
  });

  it("responds 401 when the user no longer exists", async () => {
    User.findByPk.mockResolvedValue(null);

    const response = await request(app)
      .get("/auth/me")
      .set("Authorization", `Bearer ${token}`);

    expect(response.status).toBe(401);
    expect(response.body).toEqual({ message: "Unauthorized" });
  });
});

